    "description": "人民幸福安康是推动高质量发展的最终目的。 7月30日，习近平总书记主持中共中央政治局会议。会议强调：“要多措并举加强民生保障，加大重点群体就业支持力度，做好灵活就业人员和新就业形态人员权益保障工作。抓好‘一老一小’服务保障，健全分层分类的社会救助体系。加强生态环境保护，打好‘三北’工程攻坚战，积极稳妥推进碳达峰碳中和。” 习近平总书记在庆祝中国共产党成立105周年大会上指出：“105年来，我们党始终坚守为中国人民谋幸福、为中华民族谋复兴…",
