    "description": "通过自定义udev rules实现",
    "content": "通过自定义udev rules实现 创建 /etc/udev/rules.d/81-backlight.rules 内容如下 SUBSYSTEM==\"backlight\", ACTION==\"add\", KERNEL==\"amdgpu_bl1\", ATTR{brightness}=\"15028\" 注 AMD iGPU maximum brightness 62451, amdgpu_bl1是通过 如下命令查找的 $ ls -l /sys/class/backlight"
