    "content": "新华社罗马/马德里8月1日电（记者高婧妍 孟鼎博）据意大利安莎社1日晚报道，在多方呼吁后，欧盟理事会轮值主席国爱尔兰的总理米歇尔·马丁宣布欧盟将于4日召开视频会议，讨论西班牙北非飞地休达近期面临的移民危机。 意大利总理府1日发布公告说，意大利和丹麦牵头发起联合倡议，呼吁欧盟就休达局势召开会议并协调应对。根据公告，22名欧盟国家领导人签署了一封递交至欧盟领导机构的联名信，对休达局势表示“严重关切”，强调有必要防止无序非法越境、打击非法移民贩运网络、消除一切可能刺激非法入境行为的因素，并确保欧盟采取统一、有效的应对措施…"
