    "pub_date": "2026-08-01 22:41:01",
    "author": "",
    "description": "日本政府7月31日正式设立“国家情报局”，旨在强化情报收集与分析能力。“情报先行”是日本发动侵略战争的一贯套路，国际人士表示，日本在二战时期曾通过情报操控与舆论统治等手段实行残酷殖民统治，日本政府如今再次强化国家情报体制，令人十分担忧。",
