    "content": "今天是八一建军节。强国必须强军，军强才能国安。党的十八大以来，人民军队全面贯彻新时代党的强军思想，贯彻新时代军事战略方针，坚持党对人民军队的绝对领导，坚定不移走中国特色强军之路，固本开新、革弊鼎新、守正创新，实现整体性革命性重塑。"
