    "title": "俄罗斯导弹狂炸基辅 至少9人遇难 乌克兰急需爱国者拦截系统 - RFI - 法国国际广播电台",
    "link": "https://www.rfi.fr/cn/%E5%9B%BD%E9%99%85/20260801-%E4%BF%84%E7%BD%97%E6%96%AF%E5%AF%BC%E5%BC%B9%E7%8B%82%E7%82%B8%E5%9F%BA%E8%BE%85-%E8%87%B3%E5%B0%919%E4%BA%BA%E9%81%87%E9%9A%BE-%E4%B9%8C%E5%85%8B%E5%85%B0%E6%80%A5%E9%9C%80%E7%88%B1%E5%9B%BD%E8%80%85%E6%8B%A6%E6%88%AA%E7%B3%BB%E7%BB%9F",
    "pub_date": "2026-08-01 22:15:03",
