    "description": "新华社波哥大8月1日电（记者李子健）据哥伦比亚媒体1日报道，该国北部北桑坦德省首府库库塔市一个警察局附近当天凌晨发生卡车炸弹袭击事件，造成至少10人受伤，其中包括7名警察。 当地应急部门在爆炸发生后赶赴现场，对周边进行安全排查以排除二次爆炸风险。伤者被送往附近医院接受救治。 截至目前，尚无任何组织或个人宣称制造此次袭击，相关调查正在进行中。",
    "content": "新华社波哥大8月1日电（记者李子健）据哥伦比亚媒体1日报道，该国北部北桑坦德省首府库库塔市一个警察局附近当天凌晨发生卡车炸弹袭击事件，造成至少10人受伤，其中包括7名警察。 当地应急部门在爆炸发生后赶赴现场，对周边进行安全排查以排除二次爆炸风险。伤者被送往附近医院接受救治。 截至目前，尚无任何组织或个人宣称制造此次袭击，相关调查正在进行中。"
