    "content": "新华社北京8月1日电 美国媒体披露，美军7月30日空袭伊朗期间，向一处没有军事设施的居民区投下一枚重磅炸弹，造成3人死亡。 《纽约时报》7月31日报道，根据对卫星图像、现场画面的分析和专家研判，美军7月30日对伊朗南部格什姆岛一处人口稠密的居民区投下一枚Mark-84型炸弹。这枚炸弹重达2000磅（907公斤），是美军最大的常规炸弹之一，在空袭现场留下一个直径至少9米的弹坑。 伊朗方面说，多座民宅在这次空袭中受损，其中一个五口之家中的父母和2岁的孩子死亡，另外两个孩子受伤，从废墟中被救出。 3月29日，在伊朗首都德…"
