    "title": "基民陪跑十年之果：十倍基金的玫瑰与腰斩基金的眼泪",
    "link": "https://www.infzm.com/contents/327465",
    "pub_date": "2026-08-01 21:00:00",
    "author": "南方周末研究员 廖浩伦 南方周末实习生 杨嘉苑",
    "description": "2293只权益类基金七年收益翻倍者为1118只，占比近五成；1284只权益类基金十年收益为负者仅41只。 南方周末研究员 廖浩伦 南方周末实习生 杨嘉苑 责任编辑：丰雨 七年甚至十年陪跑，一朝放榜，基金为基民绽放了时间的玫瑰抑或催生了腰斩下的眼泪？ 2026年7月31日，国内公募基金按规定披露完毕二季报，“过去7年”“过去10年”净值增长率首次出现在每一份季报中。这是国内公募基金有史以来首度亮出长跑成绩单。 这一变化源于自上而下的系统性…",
    "content": "2293只权益类基金七年收益翻倍者为1118只，占比近五成；1284只权益类基金十年收益为负者仅41只。 七年和十年收益率排名榜上，排名的两端，是十倍与腰斩的极大差距。 长跑胜者中，不以基金公司规模论英雄，亦不以单只基金规模论英雄。但仅一只基金规模超200亿元。这说明单只超大基金操作难度较大。 收益率后十名的基金几乎共享一组标签：中小基金公司、频繁换帅、基金规模“迷你”、策略不断颠覆。 南方周末研究员 廖浩伦 南方周末实习生 杨嘉苑 责任编辑：丰雨 七年甚至十年陪跑，一朝放榜，基金为基民绽放了时间的玫瑰抑或催生了腰…"
