    "content": "新华社北京8月1日电 美国《联邦政府纪事》7月31日以线上方式发布公告说，美国国务院将把面向部分国家公民的签证保证金制度长期化，50个国家的公民面临高达2万美元保证金。 这是5月15日在美国首都华盛顿拍摄的美国国务院外景。新华社记者李睿摄 公告说，这项规定适用于以商务或旅游为目的申请美国B1、B2类签证的人员。领事官员可根据具体情况，将缴纳保证金作为发放签证的条件。 新规将于8月3日在《联邦政府纪事》正式刊登时生效。适用该制度的50个国家中有30个在非洲。 美国2025年8月启动“签证保证金试行计划”。在试行阶段，…"
