    "content": "稳固本科生留校深造基本盘、到周边院校上门宣讲……地方高校新一轮研究生优质生源“争夺战”已打响。 “当前研究生优质生源区域竞争、校际竞争持续加剧，招生工作面临的新形势新任务对学校学科建设、人才培养和服务保障提出了更高要求。”据重庆交通大学网站消息，7月17日上午，学校召开2026年研究生招生工作总结会暨2027年招生工作布置会，党委书记宫辉指出，全校上下要坚持系统谋划、重点突破，统筹推进招生宣传、生源招引、培养衔接和服务保障，持续提升学校学科专业吸引力和优质生源竞争力。 宫辉强调，要前置布局精准招生宣传矩阵，做深做实…"
