    "content": "新华社北京8月1日电 题：夏季主雨带如何影响大半个中国 新华社记者刘诗平 中央气象台8月1日预报，未来3天，我国从东北延伸到西南的夏季主雨带稳定维持，强降雨、强对流天气将影响大半个中国。其中，四川盆地需高度警惕旱涝急转下的极端强降水风险，东北、华北需注意突发的强风雨影响。此外，今年第13号台风“白海豚”从5日之后将逐渐向我国东南沿海靠近，影响近海和沿海地区。 四川盆地：警惕极端降水和旱涝急转 从7月29日开始，四川盆地出现强降水，一改7月降水较常年偏少且气温偏高的天气。未来3天，四川盆地预计仍将有强降水，盆地中东部…"
