    "author": "",
    "description": "7月31日，国家医保局会同最高人民法院、最高人民检察院、公安部、财政部、国家卫生健康委、税务总局、市场监管总局、国家中医药局、国家药监局，10部门联合召开全国深化医保基金管理突出问题专项整治工作中期推进会。会议深入学习贯彻习近平总书记关于医保基金管理的重要指示批示精神，认真落实中央纪委国家监委集中整治工作部署，特别是调度会要求，坚持超常规与高质量一体发力，抓出群众满意的成效。国家医保局党组书记、局长章轲出席会议并讲话。",
